import { lexicographicSortSchema, printSchema as print } from 'graphql';

import type { GraphQLSchema } from 'graphql';

export const SCHEMA_HEADER =
  '# Generated by `pnpm codegen` (apps/api schema:emit). Do not edit by hand.\n\n';

export function printSchema(schema: GraphQLSchema): string {
  return `${SCHEMA_HEADER}${print(lexicographicSortSchema(schema))}\n`;
}
